// Kommun open data (folkmängd, elever per grade level, kommungrupp, peers).
// Generated by scripts/16-fetch-kommun-stats.js into data/kommun-stats/.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const DEFAULT_PATH = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../data/kommun-stats/kommun-stats.json',
);

export function sizeBand(folkmangd) {
  if (!Number.isFinite(folkmangd)) return null;
  if (folkmangd < 10000) return '<10k';
  if (folkmangd < 25000) return '10-25k';
  if (folkmangd < 50000) return '25-50k';
  if (folkmangd < 100000) return '50-100k';
  return '>100k';
}

class KommunStats {
  constructor(data) {
    this.data = data;
    this.records = new Map();
    for (const [kod, r] of Object.entries(data.kommuner ?? {})) {
      this.records.set(kod, {
        kod,
        namn: r.namn ?? null,
        lan: r.lan ?? null,
        folkmangd: r.folkmangd ?? null,
        sizeBand: sizeBand(r.folkmangd),
        kommungrupp: r.kommungrupp ?? null,
        peers: Array.isArray(r.peers) ? r.peers : [],
        elever: r.elever ?? {},
      });
    }
  }

  get(kod) {
    return this.records.get(kod) ?? null;
  }

  all() {
    return [...this.records.values()];
  }

  // Kommungrupp members, else same size band; never includes kod itself.
  peersOf(kod) {
    const me = this.get(kod);
    if (!me) return [];
    const same = me.kommungrupp
      ? (r) => r.kommungrupp === me.kommungrupp
      : (r) => me.sizeBand != null && r.sizeBand === me.sizeBand;
    return this.all().filter((r) => r.kod !== kod && same(r)).map((r) => r.kod);
  }

  // Sum of kommunal-regi elever over the requested grades. Introduktions-
  // programmet is part of Gymnasiet (counted once); Högskola is 0 elever.
  // null when the kommun is unknown or any needed grade is null/unknown.
  eleverIn(kod, grades) {
    const me = this.get(kod);
    if (!me) return null;
    const need = new Set();
    for (const g of grades) {
      if (g === 'Högskola') continue;
      need.add(g === 'Introduktionsprogrammet' ? 'Gymnasiet' : g);
    }
    let sum = 0;
    for (const g of need) {
      const v = me.elever[g];
      if (typeof v !== 'number' || !Number.isFinite(v)) return null;
      sum += v;
    }
    return sum;
  }
}

let memo = null;
export function loadKommunStats({ path: p, data } = {}) {
  if (data) return new KommunStats(data);
  const file = p ?? DEFAULT_PATH;
  if (memo && memo.file === file) return memo.stats;
  const stats = new KommunStats(JSON.parse(readFileSync(file, 'utf8')));
  memo = { file, stats };
  return stats;
}
